/** Source: item_menu.c → Task_WallyTutorialBagMenu */
export const Task_WallyTutorialBagMenu: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  const data = task.data;

      if (!rt.gPaletteFade.active)
      {
          switch (data[8])
          {
          case WALLY_BAG_DELAY * 1:
              m4aSongNumStart(SE_SELECT);
              SwitchBagPocket(taskId, MENU_CURSOR_DELTA_RIGHT, false);
              data[8]++;
              break;
          case WALLY_BAG_DELAY * 2:
              m4aSongNumStart(SE_SELECT);
              BagMenu_PrintCursor(data[0], COLORID_GRAY_CURSOR);
              gSpecialVar_ItemId = ITEM_POKE_BALL;
              OpenContextMenu(taskId);
              data[8]++;
              break;
          case WALLY_BAG_DELAY * 3:
              m4aSongNumStart(SE_SELECT);
              RemoveContextWindow();
              DestroyListMenuTask(data[0], 0, 0);
              RestoreBagAfterWallyTutorial();
              Task_FadeAndCloseBagMenu(taskId);
              break;
          default:
              data[8]++;
              break;
          }
      }
};

